typedef struct {
    int codigo;
    int quantidade;
} Peca;

int gravarInventario(Peca pecas[], int n, const char *caminho) {
    FILE *f = fopen(caminho, "w");
    if (f == NULL) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        fprintf(f, "%d %d\n", pecas[i].codigo, pecas[i].quantidade);
    }
    fclose(f);
    return 1;
}

int lerInventario(Peca pecas[], int limite, const char *caminho) {
    FILE *f = fopen(caminho, "r");
    if (f == NULL) {
        return 0;
    }
    int lidas = 0;
    while (lidas < limite) {
        int codigo = 0;
        int quantidade = 0;
        if (fscanf(f, "%d %d", &codigo, &quantidade) != 2) {
            break;
        }
        pecas[lidas].codigo = codigo;
        pecas[lidas].quantidade = quantidade;
        lidas = lidas + 1;
    }
    fclose(f);
    return lidas;
}

int aQuantidadeDaPeca(Peca pecas[], int n, int codigo) {
    for (int i = 0; i < n; i++) {
        if (pecas[i].codigo == codigo) {
            return pecas[i].quantidade;
        }
    }
    return -1;
}
